package com.profa.messaging;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity @Table(name="conversations")public class Conversation{@Id@GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(name="user_a") UUID userA;@Column(name="user_b") UUID userB;@Column(name="updated_at") Instant updatedAt=Instant.now();public UUID getId(){return id;}public UUID getUserA(){return userA;}public void setUserA(UUID v){userA=v;}public UUID getUserB(){return userB;}public void setUserB(UUID v){userB=v;}public Instant getUpdatedAt(){return updatedAt;}}